<script setup>
import{ref,onMounted}from'vue';import{api}from'../services/api.js';import{can}from'../stores/auth.js';import BaseModal from'../components/BaseModal.vue';import UiState from'../components/UiState.vue'
const roles=ref([]),permissions=ref([]),loading=ref(true),error=ref(''),open=ref(false),editing=ref(null),form=ref({name:'',description:'',permission_ids:[]})
async function load(){loading.value=true;try{[roles.value,permissions.value]=await Promise.all([api.get('/roles'),api.get('/permissions')])}catch(e){error.value=e.message}finally{loading.value=false}}
function create(){editing.value=null;form.value={name:'',description:'',permission_ids:[]};open.value=true}async function edit(role){editing.value=role;const detail=await api.get('/roles/'+role.id);form.value={name:detail.name,description:detail.description||'',permission_ids:detail.permission_ids};open.value=true}async function save(){try{editing.value?await api.put('/roles/'+editing.value.id,form.value):await api.post('/roles',form.value);open.value=false;await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><div class="toolbar"><p class="muted">Definiu què pot consultar i gestionar cada perfil.</p><button v-if="can('roles.manage')" class="button primary" @click="create">Nou rol</button></div><UiState :loading="loading" :error="error" :empty="!roles.length"><div class="cards-grid"><article v-for="r in roles" :key="r.id" class="card"><div class="card-head"><h2>{{r.name}}</h2><span v-if="r.is_system" class="badge neutral">Sistema</span></div><p class="muted">{{r.description||'Sense descripció'}}</p><p><strong>{{r.user_count}}</strong> usuaris</p><button v-if="can('roles.manage')" class="button secondary" @click="edit(r)">Configurar permisos</button></article></div></UiState><BaseModal :open="open" :title="editing?'Editar rol':'Crear rol'" @close="open=false"><form id="role-form" @submit.prevent="save"><label>Nom<input v-model="form.name" required></label><label>Descripció<textarea v-model="form.description" rows="2"></textarea></label><fieldset><legend>Permisos</legend><label v-for="p in permissions" :key="p.id" class="check permission"><input v-model="form.permission_ids" type="checkbox" :value="p.id"><span><strong>{{p.module_key}}</strong><small>{{p.action_key==='view'?'Consultar':'Gestionar'}}</small></span></label></fieldset></form><template #actions><button class="button secondary" @click="open=false">Cancel·lar</button><button form="role-form" class="button primary">Desar</button></template></BaseModal></template>
